import numpy as np

def raises_of(fn):
    try:
        fn()
        return 0.0
    except OverflowError:
        return 1.0

probe("np.int32('2147483648')", raises_of(lambda: np.int32('2147483648')))
probe("np.int8('128')", raises_of(lambda: np.int8('128')))
probe("np.uint8('-1')", raises_of(lambda: np.uint8('-1')))
probe("np.int32(str(np.iinfo(np.int32).max + 1))", raises_of(lambda: np.int32(str(np.iinfo(np.int32).max + 1))))

